const crypto = global.get('crypto');
if (!crypto) { node.error('Add crypto to functionGlobalContext in settings.js'); return null; }
try {
  const packet = JSON.parse(msg.payload.toString());
  if (packet.v !== 1 || packet.alg !== 'AES-256-CBC+HMAC-SHA256') throw new Error('unsupported envelope');
  if (Math.abs(Math.floor(Date.now()/1000) - Number(packet.ts)) > 120) throw new Error('stale envelope');
  const master = Buffer.from(env.get('AUTONOMIC_MASTER_KEY_HEX') || '', 'hex');
  if (master.length !== 32) throw new Error('AUTONOMIC_MASTER_KEY_HEX must be 64 hex characters');
  const aesKey = Buffer.from(crypto.hkdfSync('sha256', master, Buffer.alloc(0), Buffer.from('autonomic-tb3/aes'), 32));
  const macKey = Buffer.from(crypto.hkdfSync('sha256', master, Buffer.alloc(0), Buffer.from('autonomic-tb3/hmac'), 32));
  const signed = Buffer.from(`${packet.v}|${packet.ts}|${packet.nonce}|${packet.iv}|${packet.ct}`);
  const expected = crypto.createHmac('sha256', macKey).update(signed).digest();
  const received = Buffer.from(packet.tag, 'base64');
  if (received.length !== expected.length || !crypto.timingSafeEqual(received, expected)) throw new Error('authentication failed');
  const decipher = crypto.createDecipheriv('aes-256-cbc', aesKey, Buffer.from(packet.iv, 'base64'));
  const plaintext = Buffer.concat([decipher.update(Buffer.from(packet.ct, 'base64')), decipher.final()]);
  const data = JSON.parse(plaintext.toString('utf8'));
  const seen = context.get('seenNonces') || [];
  if (seen.includes(packet.nonce)) throw new Error('replayed envelope');
  seen.push(packet.nonce);
  if (seen.length > 2048) seen.splice(0, seen.length - 2048);
  context.set('seenNonces', seen);
  return [
    {payload: data.state || 'UNKNOWN'},
    {payload: Number(data.target_speed || 0)},
    {payload: Math.round(Number(data.battery_fraction || 0) * 100)},
    {payload: data.alert || 'No active alert'},
    {payload: data.emergency_stop ? 'BLOCKED' : 'CLEAR'},
    {payload: Number(data.completed_cycles || 0)}
  ];
} catch (error) { node.error(`Secure status rejected: ${error.message}`, msg); return null; }

